"""Manual qualification template form within the existing campaign editor theme."""

# ruff: noqa: E501 - embedded dashboard assets.

MANUAL_TEMPLATE_DIALOG = """<dialog id="manualTemplateDialog"><form id="manualTemplateForm">
<div class="modal-head"><div><h2>Add qualification template</h2><div class="sub">Check the actual search criteria below, then set qualification rules. This creates a new template; existing campaigns and runs keep their rules.</div></div><button type="button" class="close" id="closeManualTemplate" aria-label="Close template editor">x</button></div>
<div class="form-grid">
<div class="field full"><label for="manualTemplateName">Template name</label><input id="manualTemplateName" maxlength="100" required></div>
<div class="field full"><strong>Profile search criteria</strong><div class="sub">These fields control which LinkedIn profiles are fetched. The template name does not change the search.</div></div><div id="manualSearchFields" class="field full form-grid"></div><div class="field full"><label>Required matches</label><div id="manualRequiredFields" style="display:flex;gap:14px;flex-wrap:wrap"></div></div><div class="field full"><label for="manualFirmTypes">Allowed business / firm types</label><textarea id="manualFirmTypes" required placeholder="recruitment agency&#10;staffing agency"></textarea><small class="sub">One per line. The reviewer must confirm a permitted business type. Unknown facts are not assumed.</small></div>
<div class="field full"><label for="manualPriorityTitles">Priority job titles</label><textarea id="manualPriorityTitles" required placeholder="Founder&#10;Owner&#10;Operations Director"></textarea></div>
<div class="field"><label for="manualMinimumScore">Approval score threshold (0-100)</label><input id="manualMinimumScore" type="number" min="0" max="100" value="45" required></div>
<div class="field"><label for="manualMinimumSize">Minimum company size</label><input id="manualMinimumSize" type="number" min="1" max="10000" value="1" required></div>
<div class="field"><label for="manualMaximumSize">Maximum company size</label><input id="manualMaximumSize" type="number" min="1" max="10000" value="1000" required></div>
<div class="field"><label><input id="manualRequireFunds" type="checkbox" style="width:auto"> Require verified funds evidence</label><label for="manualMinimumFunds">Minimum funds (GBP, when required)</label><input id="manualMinimumFunds" type="number" min="1" max="1000000000000" value="1" required></div>
<div class="field full"><label><input id="manualPreferSelf" type="checkbox" style="width:auto"> Prefer self employed profiles</label><label for="manualSelfKeywords">Self employment evidence keywords (optional)</label><textarea id="manualSelfKeywords" placeholder="self-employed&#10;owner"></textarea></div>
<div class="field full"><small class="sub">Existing scoring stays the same: role up to 15, business type 25, location 15, size 20, self employment preference 25, supplied funds evidence 30 (total capped at 100). Set a threshold supported by the evidence you require. Qualification does not prove a customer needs your product.</small></div>
<div class="field full"><label for="manualConnectionDraft">Connection message draft</label><textarea id="manualConnectionDraft" maxlength="2000" required></textarea></div>
<div class="field full"><label for="manualMessageDraft">Follow-up message draft</label><textarea id="manualMessageDraft" maxlength="6000" required></textarea><small class="sub">Supported placeholders: {first_name}, {full_name}, {company}. Saving does not send anything; existing delivery approvals remain required. Collection and sending limits cannot be raised here.</small></div>
</div><div class="modal-actions"><span class="sub" role="status" id="manualTemplateStatus"></span><button class="btn primary" type="submit" id="saveManualTemplate">Save template</button></div>
</form></dialog>"""

MANUAL_TEMPLATE_SCRIPT = r"""<script>
const manualTemplateDialog=document.getElementById('manualTemplateDialog'),manualTemplateForm=document.getElementById('manualTemplateForm'),manualTemplateStatus=document.getElementById('manualTemplateStatus');
const manualTerms=id=>document.getElementById(id).value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);
document.getElementById('addManualTemplate').onclick=()=>{if(campaignEditingId){notice('Use New campaign to create and select another template.');return}if(!campaignSpec){notice('Wait for the campaign fields to load.');return}manualTemplateForm.reset();const fields=document.getElementById('manualSearchFields');fields.replaceChildren();for(const [key,id] of Object.entries(campaignInputs)){const field=document.createElement('div');field.className='field';const label=document.createElement('label');label.htmlFor='manualSearch-'+key;label.textContent=campaignForm.querySelector('label[for="'+id+'"]').textContent;const input=document.createElement('textarea');input.id=label.htmlFor;input.value=document.getElementById(id).value;field.append(label,input);fields.append(field)}const required=document.getElementById('manualRequiredFields');required.replaceChildren();for(const source of campaignForm.querySelectorAll('[name="campaignRequired"]')){const label=document.createElement('label');const box=document.createElement('input');box.type='checkbox';box.name='manualRequired';box.value=source.value;box.checked=source.checked;box.style.width='auto';label.append(box,document.createTextNode(' '+source.value));required.append(label)}document.getElementById('manualPriorityTitles').value=document.getElementById('campaignTitles').value;document.getElementById('manualConnectionDraft').value='Hi {first_name}, I came across your work at {company}. Open to connecting?';document.getElementById('manualMessageDraft').value='Thanks for connecting, {first_name}. Would you be open to a brief conversation about the workflows at {company}?';manualTemplateStatus.textContent='Review search terms above and enter your qualification policy before saving.';manualTemplateDialog.showModal();};
document.getElementById('closeManualTemplate').onclick=()=>manualTemplateDialog.close();
manualTemplateForm.onsubmit=async event=>{event.preventDefault();const button=document.getElementById('saveManualTemplate');button.disabled=true;manualTemplateStatus.textContent='Saving template…';const name=document.getElementById('manualTemplateName').value.trim();const spec={...campaignSpec,name,template_id:campaignTemplate.value,required_dimensions:[...manualTemplateForm.querySelectorAll('[name="manualRequired"]:checked')].map(x=>x.value),connection_degrees:[...campaignForm.querySelectorAll('[name="campaignDegree"]:checked')].map(x=>x.value),profile_limit:Number(document.getElementById('campaignProfileLimit').value),page_limit:Number(document.getElementById('campaignPageLimit').value),daily_limit:Number(document.getElementById('campaignDailyLimit').value)};for(const key of Object.keys(campaignInputs))spec[key]=manualTerms('manualSearch-'+key);const payload={name,spec,qualification:{firm_types:manualTerms('manualFirmTypes'),executive_title_priority:manualTerms('manualPriorityTitles'),minimum_score:Number(document.getElementById('manualMinimumScore').value),company_size_min:Number(document.getElementById('manualMinimumSize').value),company_size_max:Number(document.getElementById('manualMaximumSize').value),require_fund_evidence:document.getElementById('manualRequireFunds').checked,minimum_funds_gbp:Number(document.getElementById('manualMinimumFunds').value),prefer_self_employed:document.getElementById('manualPreferSelf').checked,self_employment_keywords:manualTerms('manualSelfKeywords')},connection_template:document.getElementById('manualConnectionDraft').value,message_template:document.getElementById('manualMessageDraft').value};try{const r=await fetch('/api/campaign-templates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok)throw Error(campaignError(body));campaignTemplates.push(body);campaignTemplate.add(new Option(body.name,body.id));const campaignName=document.getElementById('campaignName').value;fillCampaign(body.spec);if(campaignName.trim())document.getElementById('campaignName').value=campaignName;manualTemplateDialog.close();campaignSaveStatus.textContent='Template saved and selected. Save campaign to use it for a new search.';notice('Qualification template saved. No outreach was sent.');}catch(error){manualTemplateStatus.textContent=error.message;}finally{button.disabled=false;}};
</script>"""
